 const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');return {to:'abdelrhman.elshreef@gmail.com',subject:title,text:lines.join('\n'),html:'<!doctype html><html lang="fr"><body style="font-family:Arial;background:#f5f3ef"><main style="max-width:760px;margin:auto;padding:24px;background:white"><h1 style="background:#111a2b;color:#c9a54a;padding:20px">M&amp;B Rénovation</h1>'+lines.map(l=>'<p>'+esc(l)+'</p>').join('')+'</main></body></html>'};
}

